def sort_by_number_of_zeros(numbers: List[int]) -> List[int]:
    """ Sort numbers descendingly by number of zeros
    >>> sort_by_number_of_zeros([2, 10, 1, 0, 2])
    [2, 2, 1, 1, 0]
    """
    def number_of_zeros(number: int) -> int:
        count = 0
        while number // 10 > 0:
            count += 1
            number //= 10
        return count

    return sorted(numbers, key=number_of_zeros, reverse=True)

