def sum_digits(n: int) -> int:
    """ Given an integer, return the sum of its digits
    >>> sum_digits(56)
    11
    """
    sum = 0
    while (n != 0):
        n, r = divmod(n, 10)
        sum += r
    return sum

def fibonacci(number: int) -> int:
    """ Given an integer, return the nth fibonacci number.
    >>> fibonacci(0)
    0
    >>> fibonacci(2)
    1
    """
    if number < 0:
        return -1
    if number <= 1:
        return number
    else:
        return fibonacci(number-1)+fibonacci(number-2)

