def sum_pairs(ints: List[int], s: int) -> List[int]:
    """ For a given list of integers and a target sum, return a list of positions
    of pairs of integers that add up to the target sum. Each pair of integers corresponds
    to a position in the input list. Pairs are not returned in order of occurrence.
    """
    pairs = filter_by_substring(ints, str(s))
    if pairs:
        return sorted([str(index) for index, number in enumerate(ints) if number in pairs])
    return []


